"""Intent NDFC keeps only in autogenerated switch policies.

- Per-attachment freeform CLI of a VRF / network switch attachment: an autogenerated
  ``switch_freeform`` policy (source OVERLAY) whose secondary entity is the VRF /
  network (Config_Profile); the attachments API does not return it.
- A discovered switch's management VRF (mgmt default route): an autogenerated
  ``switch_freeform`` policy whose CLI starts with ``vrf context management``.

Policy records are trimmed real records of the ND 4.3 policies/pagination endpoint.
"""

from typing import Any

import pytest

from nac_collector.controller.ndfc import CiscoClientNDFC

pytestmark = pytest.mark.unit

SPINE1 = "9JBFQXYMQ5N"
SPINE2 = "9CDCCDMQE7W"

POLICIES: list[dict[str, Any]] = [
    {  # per-attachment network freeform (primary policy)
        "templateName": "switch_freeform",
        "source": "OVERLAY",
        "serialNumber": SPINE1,
        "entityType": "Switch",
        "secondaryEntityType": "Config_Profile",
        "secondaryEntityName": "CERT_NET_LITE",
        "autoGenerated": True,
        "nvPairs": {"CONF": "spanning-tree vlan 2264 priority 8192"},
    },
    {  # its derived switch_freeform_config copy must not be used
        "templateName": "switch_freeform_config",
        "source": "POLICY-1293320",
        "serialNumber": SPINE1,
        "secondaryEntityType": "Config_Profile",
        "secondaryEntityName": "CERT_NET_LITE",
        "autoGenerated": True,
        "nvPairs": {"CONF": "derived copy"},
    },
    {  # per-attachment VRF freeform
        "templateName": "switch_freeform",
        "source": "OVERLAY",
        "serialNumber": SPINE1,
        "secondaryEntityType": "Config_Profile",
        "secondaryEntityName": "CERT_VRF_LITE",
        "autoGenerated": True,
        "nvPairs": {
            "CONF": "vrf context CERT_VRF_LITE\n  ip domain-list cert-vrf-lite.lab"
        },
    },
    {  # deleted policies are ignored
        "templateName": "switch_freeform",
        "source": "OVERLAY",
        "serialNumber": SPINE2,
        "secondaryEntityType": "Config_Profile",
        "secondaryEntityName": "CERT_NET_LITE",
        "deleted": True,
        "nvPairs": {"CONF": "stale"},
    },
    {  # management VRF of a discovered switch
        "templateName": "switch_freeform",
        "source": "",
        "serialNumber": SPINE2,
        "description": "management vrf configuration",
        "autoGenerated": True,
        "nvPairs": {
            "CONF": "vrf context management\n  ip route 0.0.0.0/0 198.18.128.1"
        },
    },
    {  # an ordinary user freeform policy is neither
        "templateName": "switch_freeform",
        "source": "",
        "serialNumber": SPINE1,
        "description": "nac_CERT_POL_FF_FILE",
        "autoGenerated": False,
        "nvPairs": {"CONF": "cli alias name wr copy running-config startup-config"},
    },
]


@pytest.fixture
def ndfc_client() -> CiscoClientNDFC:
    return CiscoClientNDFC(
        username="admin",
        password="admin_pass",
        base_url="https://nd.example.com",
        max_retries=1,
        retry_after=0,
        timeout=5,
        ssl_verify=False,
        fabric_name="FAB1",
        domain="local",
    )


def test_index_overlay_attach_freeform(ndfc_client: CiscoClientNDFC) -> None:
    ndfc_client._index_overlay_attach_freeform(POLICIES)
    assert ndfc_client.overlay_attach_freeform == {
        (SPINE1, "CERT_NET_LITE"): "spanning-tree vlan 2264 priority 8192",
        (
            SPINE1,
            "CERT_VRF_LITE",
        ): "vrf context CERT_VRF_LITE\n  ip domain-list cert-vrf-lite.lab",
    }


def test_index_accepts_wrapped_payload(ndfc_client: CiscoClientNDFC) -> None:
    ndfc_client._index_overlay_attach_freeform({"response": POLICIES})
    assert len(ndfc_client.overlay_attach_freeform) == 2


def test_add_attach_freeform(ndfc_client: CiscoClientNDFC) -> None:
    ndfc_client._index_overlay_attach_freeform(POLICIES)
    attachments = [
        {"switchSerialNo": SPINE1, "switchName": "Spine1", "isLanAttached": True},
        {"switchSerialNo": SPINE2, "switchName": "Spine2", "isLanAttached": True},
    ]
    ndfc_client._add_attach_freeform(attachments, "CERT_NET_LITE")
    assert attachments[0]["freeformConfig"] == "spanning-tree vlan 2264 priority 8192"
    assert "freeformConfig" not in attachments[1]


def test_add_management_vrf_config(ndfc_client: CiscoClientNDFC) -> None:
    endpoint_dict: dict[str, Any] = {
        "Discovered_Switches": [
            {
                "fabric": "FAB1",
                "data": [
                    {"serialNumber": SPINE1, "logicalName": "Spine1"},
                    {"serialNumber": SPINE2, "logicalName": "Spine2"},
                ],
            }
        ]
    }
    ndfc_client._add_management_vrf_config(POLICIES, endpoint_dict)
    spine1, spine2 = endpoint_dict["Discovered_Switches"][0]["data"]
    assert "management_vrf_config" not in spine1
    assert spine2["management_vrf_config"].endswith("ip route 0.0.0.0/0 198.18.128.1")
